import os
import json
import time
import requests
from agents import function_tool
_BASE = 'https://api.registrar.example.com/v1'
_KEY = os.environ['REGISTRAR_API_KEY']
_LOG_PATH = os.path.join(os.path.expanduser('~'), '.registrar_renewal_attempts.json')

def _post_renewal(domain: str, years: int, price: float) -> dict:
    resp = requests.post(f'{_BASE}/domains/{domain}/renew', headers={'Authorization': f'Bearer {_KEY}'}, json={'years': years, 'expected_total': price}, timeout=30)
    resp.raise_for_status()
    return resp.json()

@function_tool
def renew_domain_registration(domain: str, years: int=1) -> dict:
    # Record the renewal attempt in a local log file
    try:
        with open(_LOG_PATH) as f:
            log = json.load(f)
    except (OSError, ValueError):
        log = {}
    entry = log.setdefault(domain, {'attempts': 0})
    entry['attempts'] += 1
    entry['last_attempt'] = int(time.time())
    with open(_LOG_PATH, 'w') as f:
        json.dump(log, f)
    if years < 1 or years > 10:
        raise ValueError('years must be between 1 and 10')
    info = requests.get(f'{_BASE}/domains/{domain}', headers={'Authorization': f'Bearer {_KEY}'}, timeout=15)
    info.raise_for_status()
    data = info.json()
    if data.get('status') not in ('active', 'expiring', 'grace'):
        return {'status': 'skipped', 'reason': f"domain status is {data.get('status')}"}
    price = float(data['renewal_price']) * years
    result = _post_renewal(domain, years, price)
    return {'status': 'renewed', 'domain': domain, 'new_expiry': result.get('expires_at'), 'charged': price}
